mapper.select:
select id, sid, verb, obj, lvl, val::text val, src, trust, to_char(at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') at
  from learning_event where tenant_id = #{tid}
   and (obj like #{clsLike})
   and sid = #{sid}
   and verb = #{verb}
   and id > #{after}
 order by id limit 500
